          '[Do] you walk to school? Yes, I do.|你走路上学吗？是的。',
          "[Does] your father cook? No, he doesn't.|你爸爸做饭吗？不做。",
          "Is your bag red [or] blue? It's blue.|你的包是红色的还是蓝色的？是蓝色的。",
          'Would you like rice [or] noodles? Noodles, please.|你想吃米饭还是面条？面条，谢谢。',
