        rule: `<p>主动语态：主语是动作的执行者（Many people <b>speak</b> English）。被动语态：主语是动作的承受者（English <b>is spoken</b> by many people）。</p>
<p>被动语态 = <b>be + 过去分词</b>，时态由 be 体现；动作的执行者用 <b>by</b> 引出，不重要时可以省略。</p>`,
