          'This is a bike [made] in China.|这是一辆中国制造的自行车。',
          'We are all [excited] about the trip.|我们都对这次旅行感到兴奋。',
          'The film was [boring], so I felt [bored].|这部电影很无聊，所以我觉得很无聊。',
          'She looked [surprised] at the news.|她听到这个消息时显得很吃惊。',
