          '[If only] I [could] fly!|要是我会飞就好了！',
          'The doctor suggested that he [take] more exercise.|医生建议他多锻炼。',
          'It is high time we [went] to bed.|我们早该睡觉了。',
          'She talks as if she [knew] everything.|她说起话来好像什么都懂似的。',
